import{_ as a,H as r,f as e,i as d}from"./chunks/framework.nyB-Xt5O.js";const b=JSON.parse('{"title":"业务指标体系建设","description":"","frontmatter":{},"headers":[],"relativePath":"learning-paths/path-2-core/04-metrics.md","filePath":"learning-paths/path-2-core/04-metrics.md","lastUpdated":1779798726000}'),o={name:"learning-paths/path-2-core/04-metrics.md"};function n(i,t,l,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="业务指标体系建设" tabindex="-1">业务指标体系建设 <a class="header-anchor" href="#业务指标体系建设" aria-label="Permalink to &quot;业务指标体系建设&quot;">​</a></h1><blockquote><p>指标体系是连接业务和理解业务的桥梁。深入参考请见 <a href="/data-analysis-learning/knowledge-map/km-7-metrics/">KM 7. 业务指标体系</a>。</p></blockquote><h2 id="主流指标框架" tabindex="-1">主流指标框架 <a class="header-anchor" href="#主流指标框架" aria-label="Permalink to &quot;主流指标框架&quot;">​</a></h2><h3 id="aarrr-海盗指标" tabindex="-1">AARRR（海盗指标） <a class="header-anchor" href="#aarrr-海盗指标" aria-label="Permalink to &quot;AARRR（海盗指标）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>核心指标</th><th>关注点</th></tr></thead><tbody><tr><td>Acquisition 获取</td><td>新增用户、CAC</td><td>渠道效率</td></tr><tr><td>Activation 激活</td><td>激活率、首次核心行为</td><td>第一印象</td></tr><tr><td>Retention 留存</td><td>次日/7日/30日留存</td><td>产品粘性</td></tr><tr><td>Revenue 收入</td><td>LTV、ARPU、GMV</td><td>商业价值</td></tr><tr><td>Referral 传播</td><td>K-factor、邀请率</td><td>增长飞轮</td></tr></tbody></table><h2 id="北极星指标" tabindex="-1">北极星指标 <a class="header-anchor" href="#北极星指标" aria-label="Permalink to &quot;北极星指标&quot;">​</a></h2><p>定义原则：<strong>指引方向、可拆解、可衡量、与业务价值对齐</strong></p><p>示例：</p><ul><li>Spotify → <strong>用户收听时长</strong></li><li>Airbnb → <strong>预订过夜数</strong></li><li>电商 → <strong>GMV</strong></li></ul><h2 id="行业核心指标速查" tabindex="-1">行业核心指标速查 <a class="header-anchor" href="#行业核心指标速查" aria-label="Permalink to &quot;行业核心指标速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行业</th><th>核心指标</th></tr></thead><tbody><tr><td>电商</td><td>GMV、客单价、复购率、退货率</td></tr><tr><td>金融</td><td>LTV/CAC、逾期率、首笔率、复借率</td></tr><tr><td>内容</td><td>DAU、人均时长、内容消费渗透率</td></tr><tr><td>SaaS</td><td>MRR/ARR、Churn Rate、NPS</td></tr></tbody></table><blockquote><p>深入了解请参阅 <a href="/data-analysis-learning/knowledge-map/km-7-metrics/">KM 7. 业务指标体系</a>。</p></blockquote>',12)])])}const u=a(o,[["render",n]]);export{b as __pageData,u as default};
